// Остальные классы ДнД 2024: умения по уровням, подклассы, подсказки.
// Подключается после hints.js и дополняет CLASS_DATA и справочник умений.
// F(уровень, название, что делает, когда применять) — записывает подсказку и возвращает пару [уровень, название].
const F = (lv, name, what, when) => {
  const k = hintKey(name);
  if (!FEATURE_HINT_INDEX.has(k)) { const h = { names: [name.toLowerCase()], meta: '', what, when }; FEATURE_HINTS.push(h); FEATURE_HINT_INDEX.set(k, h); }
  return [lv, name];
};
const HALF_SLOTS = [[2], [2], [3], [3], [4, 2], [4, 2], [4, 3], [4, 3], [4, 3, 2], [4, 3, 2], [4, 3, 3], [4, 3, 3], [4, 3, 3, 1], [4, 3, 3, 1], [4, 3, 3, 2], [4, 3, 3, 2], [4, 3, 3, 3, 1], [4, 3, 3, 3, 1], [4, 3, 3, 3, 2], [4, 3, 3, 3, 2]];
