const WM = (lv) => F(lv, 'Мастерство оружия', 'Вы пользуетесь приёмами мастерства у выбранных видов оружия (у воина их три, у остальных два). Виды можно сменить после долгого отдыха.', 'Приём написан у оружия в листе: например «Толчок» или «Подсечка». Применяйте его при каждом попадании.');
const EA = (lv) => F(lv, 'Дополнительная атака', 'Действием «Атака» вы бьёте дважды. У воина с 11 уровня три атаки, с 20 — четыре. Бард коллегии доблести может заменить одну из атак заговором.', 'Каждый ход, когда атакуете оружием.');
const EV = (lv) => F(lv, 'Увёртливость', 'Спасбросок Ловкости на половину урона: при успехе урона нет вовсе, при провале половина.', 'Работает само против огненных шаров и дыхания драконов.');
const FS = (lv) => F(lv, 'Боевой стиль', 'Вы выбираете черту боевого стиля: стрельба, защита, дуэлянт, бой двумя оружиями и другие.', 'Выберите стиль под своё оружие и впишите его в описание умения.');

